import difflib

def satir_farki(a: list[str], b: list[str]) -> list[tuple[str, str]]:
    """
    a listesini b'ye çeviren minimal düzenleme dizisi döndürür.
    Format: (" ", satır), ("-", satır), ("+", satır)
    """
    matcher = difflib.SequenceMatcher(None, a, b)
    result = []

    # SequenceMatcher get_opcodes() şu sırayla döner: 
    # 'replace', 'delete', 'insert', 'equal'
    # Ancak bizden istenen format ve kural şudur:
    # " " (ortak), "-" (silinen), "+" (eklenen)
    # Ardışık değişikliklerde silmeler eklemelerden önce gelmeli.
    # SequenceMatcher opcodes zaten mantıklı bir sıra sunar.

    for tag, i1, i2, j1, j2 in matcher.get_opcodes():
        if tag == 'equal':
            for k in range(i1, i2):
                result.append((" ", a[k]))
        elif tag == 'delete':
            for k in range(i1, i2):
                result.append(("-", a[k]))
        elif tag == 'insert':
            for k in range(j1, j2):
                result.append(("+", b[k]))
        elif tag == 'replace':
            # Replace işlemi aslında bir silme ve bir eklemedir.
            # Kural: Silmeler eklemelerden önce gelmeli.
            for k in range(i1, i2):
                result.append(("-", a[k]))
            for k in range(j1, j2):
                result.append(("+", b[k]))

    return result

if __name__ == "__main__":
    # Basit testler
    assert satir_farki(["a", "b"], ["a", "c"]) == [(" ", "a"), ("-", "b"), ("+", "c")]
    assert satir_farki(["a", "b", "c"], ["a", "d", "c"]) == [(" ", "a"), ("-", "b"), ("+", "d"), (" ", "c")]
    print("Temel testler geçti.")

